from fractions import Fraction

count = int(input())
for i in range(count):
    parts = input().split()
    if parts[0] == "R":
        cut = parts.index("/")  # the position of the "/" in the list
        top = [Fraction(v) for v in parts[1:cut]]
        bottom = [Fraction(v) for v in parts[cut + 1:]]
        p, q = len(top) - 1, len(bottom) - 1  # the degrees
        ratio = top[0] / bottom[0]
        if p == q:
            answer = f"limit {ratio}"
        elif p < q:
            answer = "limit 0"
        elif ratio > 0:
            answer = "diverges to oo"
        else:
            answer = "diverges to -oo"
    else:
        r = Fraction(parts[1])
        if -1 < r < 1:
            answer = "limit 0"
        elif r == 1:
            answer = "limit 1"
        elif r > 1:
            answer = "diverges to oo"
        else:
            answer = "diverges"
    print(f"Problem {i + 1}: {answer}")

from fractions import Fraction

count = int(input())
for i in range(count):
    a, b, p = [int(v) for v in input().split()]
    if p > 0:
        top = abs(a) + abs(b)
        n = 1
        while Fraction(top, n**p) >= Fraction(1, 100):
            n = n + 1
        print(f"Problem {i + 1}: |a_n| <= {top}/n^{p}, limit 0, within 0.01 from n = {n}")
    elif b == 0:
        print(f"Problem {i + 1}: constant {a}, limit {a}")
    else:
        print(f"Problem {i + 1}: even terms {a + b}, odd terms {a - b}, diverges")

from fractions import Fraction
import math

count = int(input())
for i in range(count):
    parts = input().split()
    if parts[0] == "frac":
        p, q, r, s = [int(v) for v in parts[1:]]
        d = p * s - q * r
        first, limit = Fraction(p + q, r + s), Fraction(p, r)
        if d > 0:
            print(f"Problem {i + 1}: increasing from {first} to {limit}")
        elif d < 0:
            print(f"Problem {i + 1}: decreasing from {first} to {limit}")
        else:
            print(f"Problem {i + 1}: constant {first}")
    else:
        c = int(parts[1])
        n = 0
        while Fraction(c, n + 1) >= 1:
            n = n + 1
        print(f"Problem {i + 1}: decreasing from n = {n}, largest term {Fraction(c**n, math.factorial(n))}")

from fractions import Fraction

count = int(input())
for i in range(count):
    m, c, a0 = [Fraction(v) for v in input().split()]
    a = a0
    line = ""
    for k in range(5):
        line = line + f" {a}"
        a = m * a + c
    print(f"Problem {i + 1}: terms{line}")
    if m == 1:
        if c == 0:
            print("  constant")
        else:
            print("  no fixed point: diverges")
    else:
        L = c / (1 - m)
        if a0 == L:
            print(f"  constant at L = {L}")
        elif abs(m) < 1:
            print(f"  converges to L = {L}")
        else:
            print(f"  diverges, though L = {L}")
